        display: flex;
        justify-content: space-between;
        user-select: none;
        height: 100%;

        .back {
            position: relative;
            height: 100vh;
            height: 100dvh;
            width: 30%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 8px;
            overflow: hidden;

            .back__glow {
                position: absolute;
                inset: 0;
                pointer-events: none;
            }

            p {
                position: relative;
                z-index: 1;
                transition: 0.3s;
                font-family: $font-family;
                font-weight: 600;
                font-size: 0.88rem;
                text-transform: uppercase;
                color: #a1a1aa;
            }

            span {
                position: relative;
                z-index: 1;
                font-family: $font-family;
                font-size: 0.75rem;
                color: #718078;
            }
        }

        .leftBack {
            border-right: solid 2px #1b221e;

            .back__glow {
                background-color: rgba(239, 68, 68, 0.14);
            }

            &:hover p,
            &:focus-visible p {
                color: rgb(252, 165, 165);
            }
        }

        .rightBack {
            border-left: solid 2px #1b221e;

            .back__glow {
                background-color: rgba(34, 197, 94, 0.14);
            }

            &:hover p,
            &:focus-visible p {
                color: rgb(134, 239, 172);
            }
        }
    }
}

@media (max-width: 768px) {
    .statement {
        &__backs .back {
            width: 22%;

            span {
                display: none;
            }
        }

        &__card {
            padding: 40px 24px;
        }

        &__result {
            padding: 36px 24px;
        }
    }
}

